                            "    tabla = [0, 1]",
                            "    i = 2",
                            "",
                            "    mientras i <= n",
                            "        siguiente = tabla[i - 1] + tabla[i - 2]",
                            "        AGREGA(tabla, siguiente)",
                            "        i = i + 1",
                            "",
                            "    retornar tabla[n]"
